import assert from 'node:assert/strict';import {mkdtemp,cp,readFile,writeFile,rm,mkdir} from 'node:fs/promises';import path from 'node:path';import {tmpdir} from 'node:os';import {chromium} from 'playwright';import AxeBuilder from '@axe-core/playwright';import {applyValidationSchema} from '../../engine/form-validation.mjs';import {run} from '../../engine/pipeline.mjs';import {serveStatic} from '../../engine/static.mjs';import {visualScore} from '../../engine/verify.mjs';
const artifact=path.resolve('artifacts/platform/cf7-heldout'),temp=await mkdtemp(path.join(tmpdir(),'cf7-validation-')),evidence=path.join(artifact,'validation-states');let browser,server;const cases=[];let sourcePosts=0;const started=Date.now();
try{
 await mkdir(evidence,{recursive:true});await cp(path.join(artifact,'project'),temp,{recursive:true});for(const file of ['form-export.mjs','component-forms.js'])await cp(path.resolve('scripts',file),path.join(temp,'scripts',file));
 const config=JSON.parse(await readFile(path.join(temp,'forms.json'))),definition=config.forms.find(f=>f.route==='/studio-news/');const schema=await fetch('http://127.0.0.1:9438/wp-json/contact-form-7/v1/contact-forms/'+definition.sourceFormId+'/feedback/schema');assert.equal(schema.status,200);applyValidationSchema(definition,await schema.json());definition.delivery={endpoint:'/validation-test'};const visit=config.forms.find(f=>f.route==='/studio-visit/');const visitSchema=await fetch('http://127.0.0.1:9438/wp-json/contact-form-7/v1/contact-forms/'+visit.sourceFormId+'/feedback/schema');assert.equal(visitSchema.status,200);applyValidationSchema(visit,await visitSchema.json());visit.delivery={endpoint:'/validation-test'};await writeFile(path.join(temp,'forms.json'),JSON.stringify(config));const buildStart=Date.now();await run(process.execPath,['scripts/build.mjs'],{cwd:temp,timeout:120000});const buildMs=Date.now()-buildStart;
 server=await serveStatic(path.join(temp,'output'));browser=await chromium.launch({channel:'chrome'});
 for(const width of [1440,390]){
  const results=[];
  for(const [name,origin]of [['source','http://127.0.0.1:9438'],['export',server.url]]){
   const context=await browser.newContext({viewport:{width,height:900},reducedMotion:'reduce'}),page=await context.newPage();await page.route('**/*',route=>{if(route.request().method()==='POST'){sourcePosts++;return route.abort();}return route.continue();});await page.goto(origin+'/studio-news/',{waitUntil:'networkidle'});await page.evaluate(()=>document.fonts.ready);const form=page.locator('form.wpcf7-form');
   await form.locator('[name="full-name"]').fill('Fixture visitor');await form.locator('[name="topics[]"]').selectOption(['Architecture']);await form.locator('[name="newsletter-policy"]').check();await form.locator('[name="subscriber-email"]').fill('bad');await form.locator('[name="full-name"]').click();await page.waitForFunction(()=>document.querySelectorAll('.wpcf7-not-valid-tip').length===1);
   const tip=form.locator('.wpcf7-not-valid-tip');assert.equal(await tip.textContent(),'Please enter an email address.');assert.equal(await form.locator('[name="subscriber-email"]').getAttribute('aria-invalid'),'true');assert.equal(await form.locator('[name="full-name"]').evaluate(e=>document.activeElement===e),true);
   const file=path.join(evidence,name+'-'+width+'.png');await form.screenshot({path:file,animations:'disabled',caret:'hide'});const dimensions=await form.boundingBox(),style=await tip.evaluate(e=>({color:getComputedStyle(e).color,fontSize:getComputedStyle(e).fontSize,display:getComputedStyle(e).display}));const axe=await new AxeBuilder({page}).include('form.wpcf7-form').analyze();
   const described=await form.locator('[name="subscriber-email"]').evaluate(e=>(e.getAttribute('aria-describedby')||'').split(/\s+/).filter(Boolean).every(id=>document.getElementById(id)));assert.equal(described,true);
   await form.locator('[name="subscriber-email"]').fill('valid@example.test');await page.keyboard.press('Tab');await page.waitForFunction(()=>document.querySelectorAll('.wpcf7-not-valid-tip').length===0);assert.equal(await form.locator('[name="subscriber-email"]').getAttribute('aria-invalid'),'false');results.push({name,file,dimensions,style,violations:axe.violations.map(v=>({id:v.id,impact:v.impact,nodes:v.nodes.length}))});await context.close();
  }
  const [source,rebuilt]=results;assert.deepEqual(rebuilt.style,source.style);assert.ok(Math.abs(rebuilt.dimensions.height-source.dimensions.height)<=1);const pixel=visualScore(await readFile(source.file),await readFile(rebuilt.file));assert.ok(pixel>=.99,'Validation state differs: '+pixel);assert.deepEqual(rebuilt.violations,source.violations);cases.push({width,pixel,source,rebuilt});
 }
 const rules=[],groupStates=[];
 for(const width of [1440,390])for(const [name,origin]of [['source','http://127.0.0.1:9438'],['export',server.url]]){
  const page=await browser.newPage({viewport:{width,height:900}});await page.route('**/*',r=>{if(r.request().method()==='POST'){sourcePosts++;return r.abort();}return r.continue();});await page.goto(origin+'/studio-visit/',{waitUntil:'networkidle'});const values=[];
  for(const [field,value]of [['telephone','invalid text'],['telephone','123456789'],['telephone','+1 (234) 567-8901'],['telephone','1234567890123456'],['telephone','123456789#123'],['website','ftp://example.test'],['website','https://example.test/path']]){const input=page.locator('[name="'+field+'"]');await input.fill(value);await input.press('Tab');await page.waitForTimeout(100);values.push({field,value,invalid:await input.getAttribute('aria-invalid')==='true'});}
  await page.locator('[name=telephone]').fill('123456789');await page.locator('[name=visitors]').fill('4');await page.locator('[name="visit-date"]').fill('2027-05-10');await page.locator('[name=notes]').fill('Notes');await page.locator('[name=telephone]').click();await page.waitForFunction(()=>document.querySelectorAll('.wpcf7-not-valid-tip').length===2);
  const groups=[];for(const field of ['weekdays[]','brief']){const input=page.locator('[name="'+field+'"]'),wrapper=input.first().locator('xpath=ancestor::*[contains(@class,"wpcf7-form-control-wrap")][1]');const file=path.join(evidence,name+'-'+width+'-'+field.replace(/[^a-z]/g,'')+'.png');await wrapper.screenshot({path:file,animations:'disabled',caret:'hide'});groups.push({field,file,message:await wrapper.locator('.wpcf7-not-valid-tip').textContent()});}
  groupStates.push({name,width,groups});rules.push({name,width,values});await page.close();
 }
 for(let pair=0;pair<groupStates.length;pair+=2)for(let i=0;i<groupStates[pair].groups.length;i++){const source=groupStates[pair].groups[i],rebuilt=groupStates[pair+1].groups[i];assert.equal(rebuilt.message,source.message);const pixel=visualScore(await readFile(source.file),await readFile(rebuilt.file));assert.ok(pixel>=.99,'Grouped validation visual mismatch '+source.field+': '+pixel);rebuilt.pixel=pixel;}
 for(let pair=0;pair<rules.length;pair+=2)assert.deepEqual(rules[pair+1].values,rules[pair].values);assert.ok(rules[0].values.some(x=>x.invalid));assert.ok(rules[0].values.some(x=>!x.invalid));
 assert.equal(sourcePosts,0);const report={cases,rules,groupStates,buildMs,elapsedMs:Date.now()-started,sourceSubmissions:sourcePosts,aiCalls:0};await writeFile(path.join(evidence,'report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify({cases:cases.length,minPixel:Math.min(...cases.map(c=>c.pixel)),buildMs,sourceSubmissions:0,aiCalls:0}));
}finally{await browser?.close();await server?.close();await rm(temp,{recursive:true,force:true});}
